// Checks for the agent's SolidWorks API cheat sheet (agent/cad/swApiCheatsheet.ts, generated by tools/dev/ApiCheatSheet):
// it stays under its token budget (characters / 4), names every member in members.json, and is in the SolidWorks profile's
// API section (so it is in the cached system prompt). The tool's `check` command verifies the signatures against the interop.
// Run from the ui folder:  node src/lib/checks/cheatsheet.check.mjs   (lib.check.mjs runs it too)
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { SW_API_CHEATSHEET } from "../../agent/cad/swApiCheatsheet.ts";

const spec = JSON.parse(readFileSync(new URL("../../../../tools/dev/ApiCheatSheet/members.json", import.meta.url), "utf8"));
// solidworks.ts is read as text: it imports the sheet without a .ts extension (vite style), which node can't resolve.
const profile = readFileSync(new URL("../../agent/cad/solidworks.ts", import.meta.url), "utf8");
const sheet = SW_API_CHEATSHEET;
const lines = sheet.split("\n");

let n = 0;
const t = (name, fn) => {
  fn();
  n++;
  console.log("ok -", name);
};

t("the cheat sheet is under its token budget", () => {
  const budget = spec.budgetTokens ?? 3500;
  const tokens = Math.ceil(sheet.length / 4);
  assert.ok(tokens <= budget, `the cheat sheet is ~${tokens} tokens (chars/4), over its budget of ${budget}: trim members.json or notes.md`);
});

t("the cheat sheet names every member in members.json", () => {
  const missing = [];
  for (const group of spec.groups) {
    assert.ok(lines.includes(`## ${group.title}`), `group heading "${group.title}" missing`);
    for (const entry of group.members) {
      const name = typeof entry === "string" ? entry : entry.member;
      if (name.includes(".")) {
        // a method "IX.Member(" or a property "IX.Member {"
        if (!lines.some((l) => l.startsWith(`${name}(`) || l.startsWith(`${name} {`))) missing.push(name);
      } else {
        const line = lines.find((l) => l.startsWith(`${name}: `));
        if (!line) missing.push(name);
        else for (const v of entry.values ?? []) if (!line.includes(` ${v}=`) && !line.includes(`: ${v}=`)) missing.push(`${name}.${v}`);
      }
      if (typeof entry === "object" && entry.hint && !lines.some((l) => l.startsWith(name) && l.endsWith(` - ${entry.hint.trim()}`))) missing.push(`${name} (hint)`);
    }
  }
  assert.deepEqual(missing, [], "regenerate the sheet with tools/dev/ApiCheatSheet");
});

t("the sheet carries the gotchas and sits in the SolidWorks API section", () => {
  assert.ok(sheet.includes("## Gotchas"));
  for (const must of ["IPartDoc", "SelectData", "object[]", "radians", "PostSplitBody2", "Mark 1"]) assert.ok(sheet.includes(must), must);
  assert.match(profile, /import \{ SW_API_CHEATSHEET \} from "\.\/swApiCheatsheet";/);
  const api = profile.replace(/\r\n/g, "\n").match(/\n {4}api: `([\s\S]*?)`,\n/);
  assert.ok(api, "solidworks.ts: sections.api not found");
  assert.ok(api[1].includes("${SW_API_CHEATSHEET}"), "solidworks.ts must include SW_API_CHEATSHEET in sections.api");
  assert.match(api[1], /cheat sheet/);
  assert.match(api[1], /search_sw_api/);
});

console.log(`${n} cheat sheet checks passed`);
